/**
 * Sets the spacing between adjacent sections.
 * @param spacing - The spacing to apply.
 * @platform ios 17.0+
 */ export const listSectionSpacing = (spacing)=>{
    if (typeof spacing === 'number') {
        return createModifier('listSectionSpacing', {
            spacing: 'custom',
            value: spacing
        });
    }
    return createModifier('listSectionSpacing', {
        spacing
    });
};
